import{z as r,x as A,o,c as d,q as n,j as l,D as E,d as a,s as i,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"对话状态与停止语义","description":"","frontmatter":{"title":"对话状态与停止语义","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-dialogue-state-stop.md","filePath":"llm/dec-dialogue-state-stop.md","lastUpdated":1791413859000}'),p={name:"llm/dec-dialogue-state-stop.md"};function c(h,e,D,f,m,g){const s=A("Mermaid");return o(),d("div",null,[e[2]||(e[2]=n('<h1 id="对话状态与停止语义" tabindex="-1">对话状态与停止语义 <a class="header-anchor" href="#对话状态与停止语义" aria-label="Permalink to &quot;对话状态与停止语义&quot;">​</a></h1><div class="epigraph"><p>「为什么停了」至少有四种答案；把这四种答案都折叠成 finished，多轮对话就会在半句话上续写。</p><footer>—— 据 OpenAI 兼容接口的 finish_reason 约定与 Hugging Face chat template 机制整理</footer></div><p><a href="/llm/dec-logit-processor-stack">上一课</a>把每一步的 logits 改写钉成栈。本课问序列何时收口。单请求的零件基础课已备齐：<a href="/llm/stop-sequences">stop sequences</a> 写了结束 token、停用串与长度预算三分，<a href="/llm/chat-template">chat template</a> 写了角色渲染与结束符契约，<a href="/llm/function-calling">function calling</a> 写了工具协议。本课把它们装进<strong>多轮服务</strong>：停止语义是会话状态的函数，不是解码器的常数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多轮服务里，「这一步之后停」的含义随状态变化。助手正常说完，结束符是模板规定的特殊 token；<span class="marginnote">术语翻译：结束符通常叫 EOS（end of sequence），是词表里一个专门表示「我说完了」的特殊 token，不是普通文字。它由训练时的对话模板规定——模型生成出它，解码器才知道该收口；换一个模型，这个 token 的编号和写法可能完全不同。</span>工具调用回合里，结束标签是协议边界，切掉之后还要执行工具、把结果拼回来继续生成；<code>max_tokens</code> 触发的截断在语言学上没有结束，若当正常输出回填历史，下一轮从半句话续写；安全过滤中断是另一种 finish。无状态服务每个请求只看到一次解码，天然不知道这些差别；把所有终止都叫 <code>finished</code>，会话层就失去了区分「说完了」「被截断」「触发协议边界」的信息。缺口是：服务侧要有一份随会话演进的停止状态机，决定每轮用哪些终止条件、结束之后历史怎么记。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>每轮记录 finish_reason，全集至少四项</strong>：<code>stop</code>（EOS 或停用串命中）、<code>length</code>（预算截断）、<code>tool</code>（协议边界命中、工具待执行）、<code>filter</code>（安全中断）。返回给客户端的是这份全集，不是布尔。</p><p><strong>历史回填按 finish 分支</strong>：<code>stop</code> 轮按原文回填；<code>length</code> 轮要么补显式「未完待续」标记、要么拒绝静默续写；<code>tool</code> 轮回填的是「调用片段加工具结果」的完整回合；<code>filter</code> 轮回填占位符而非被滤内容。回填文本与交付文本的一致性归后处理管线，本课钉的是：<strong>截断绝不当正常结束</strong>。</p><p><strong>终止条件随状态装配</strong>：助手轮把模板结束符放进 eos 集合（<a href="/llm/stop-sequences">stop 课</a>的分工）；工具轮把结束标签放进 stop 列表并挂起增量交付；两者来源都是<a href="/llm/special-tokens">模板与特殊 token 契约</a>，不靠运行时猜字符串。取消与超时也进状态机：它们是调用方中止，<code>finish</code> 标记要如实区分。</p>',9)),(o(),l(B,null,{default:E(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TURN%5B%22%E6%96%B0%E4%B8%80%E8%BD%AE%E8%A7%A3%E7%A0%81%22%5D%20--%3E%20ST%7B%22%E4%BC%9A%E8%AF%9D%E7%8A%B6%E6%80%81%22%7D%0A%20%20ST%20--%3E%7C%E5%8A%A9%E6%89%8B%E8%BD%AE%7C%20EOS%5B%22eos%20%E9%9B%86%E5%90%88%20%2B%20%E5%81%9C%E7%94%A8%E4%B8%B2%22%5D%0A%20%20ST%20--%3E%7C%E5%B7%A5%E5%85%B7%E8%BD%AE%7C%20TAG%5B%22%E7%BB%93%E6%9D%9F%E6%A0%87%E7%AD%BE%20stop%20%2B%20%E6%8C%82%E8%B5%B7%E6%B5%81%E5%BC%8F%22%5D%0A%20%20EOS%20--%3E%20FR%7B%22finish_reason%22%7D%0A%20%20TAG%20--%3E%20FR%0A%20%20FR%20--%3E%7Cstop%7C%20H1%5B%22%E6%8C%89%E5%8E%9F%E6%96%87%E5%9B%9E%E5%A1%AB%E5%8E%86%E5%8F%B2%22%5D%0A%20%20FR%20--%3E%7Clength%7C%20H2%5B%22%E6%A0%87%E8%AE%B0%E6%9C%AA%E5%AE%8C%EF%BC%8C%E6%8B%92%E7%BB%9D%E9%9D%99%E9%BB%98%E7%BB%AD%E5%86%99%22%5D%0A%20%20FR%20--%3E%7Ctool%7C%20H3%5B%22%E6%89%A7%E8%A1%8C%E5%B7%A5%E5%85%B7%EF%BC%8C%E6%8B%BC%E5%9B%9E%E7%BB%93%E6%9E%9C%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20FR%20--%3E%7Cfilter%7C%20H4%5B%22%E5%8D%A0%E4%BD%8D%E7%AC%A6%E5%9B%9E%E5%A1%AB%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("为什么必须状态化：训练分布里结束符是渲染模板的一部分（"),t("a",{href:"/llm/chat-template"},"chat template 课"),a("的结论——模板与权重同为契约）。会话层若把截断历史原样回放，模型见到的条件前缀是训练时没见过的「半句话」形态，下一轮的续写质量崩坏却无报错——这是 OOD，不是能力问题。"),t("span",{class:"marginnote"},"术语翻译：OOD 即 out of distribution（分布外）——输入长成了训练时没见过的形状。模型只学过「完整回合后面接新回合」，从没学过「半句话后面接什么」，于是只能瞎接；这种错不会抛异常，只有下游质量悄悄变差。"),a("工具轮同理：结束标签若既不进 stop 也不进 eos，模型会在标签后继续「替系统写结果」；若把工具结果误当用户输入拼错角色，模板层直接坏掉。")],-1)),(o(),l(B,null,{default:E(()=>[i(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OK%5B%22stop%20%E8%BD%AE%EF%BC%9A%E5%8E%9F%E6%96%87%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20%20%20A1%5B%22%E5%AE%8C%E6%95%B4%E5%9B%9E%E5%90%88%20%2B%20%E7%BB%93%E6%9D%9F%E7%AC%A6%22%5D%20--%3E%20A2%5B%22%E5%89%8D%E7%BC%80%E5%9C%A8%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E5%86%85%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E7%BB%AD%E5%86%99%E6%AD%A3%E5%B8%B8%22%5D%0A%20%20end%0A%20%20subgraph%20TR%5B%22length%20%E8%BD%AE%EF%BC%9A%E5%8E%9F%E6%A0%B7%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20%20%20B1%5B%22%E5%8D%8A%E5%8F%A5%E8%AF%9D%EF%BC%8C%E6%97%A0%E7%BB%93%E6%9D%9F%E7%AC%A6%22%5D%20--%3E%20B2%5B%22%E5%89%8D%E7%BC%80%E5%BD%A2%E6%80%81%E8%AE%AD%E7%BB%83%E6%97%B6%E6%B2%A1%E8%A7%81%E8%BF%87%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%BB%AD%E5%86%99%E8%B4%A8%E9%87%8F%E5%B4%A9%E5%9D%8F%EF%BC%8C%E4%B8%94%E6%97%A0%E6%8A%A5%E9%94%99%22%5D%0A%20%20end%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<p><span class="marginnote">这张图回答「为什么截断绝不能当正常结束」：两种回填在日志里看起来一模一样，差别只在 finish_reason 字段。左边的模型见过这种前缀，右边的没见过——所谓「多轮对话越聊越胡说」，很多就是这么来的。</span></p><p>停止语义与投机解码的交互在基础课已钉过：草稿上的提前命中不能提交，以已接受文本为准。会话状态机加上一条：跨轮的终止条件配置（eos 集合、stop 列表）属于会话元数据，跟随会话路由迁移，换引擎不能丢。</p><p><span class="marginnote">最常见的多轮 bug 是把 finish_reason=length 的轮次按正常输出回填：日志里一切正常，只有 finish 字段知道模型从半句话续写。验收脚本要按 finish_reason 分桶统计续写质量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>停止语义不提供安全：模型可以在命中终止条件前写完违规内容，内容安全是独立分类通道（<a href="/llm/stop-sequences">stop 课</a>的老边界）。多结束符集合跨模型迁移要重测：同一逻辑结束在不同词表里有不同表面编码，只做字符串匹配会漏。<span class="marginnote">常见误区：初学者以为结束符就是一段固定字符串（比如 <code>&lt;/s&gt;</code>），写个字符串比对就完事。实际上很多结束符是特殊 token，可能在文本里没有对应的字面形式，或者同一段文字在不同 tokenizer 下切法不同——字符串匹配要么漏停、要么误停，必须走 token id 层的契约。</span>会话粘性与路由归调度课程；本课钉的是状态机本身。下一课管收口之前的每一段怎么交付：流式与增量解析。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>finish_reason 至少四项：stop、length、tool、filter；全部终止都进状态机，含取消与超时。</li><li>历史回填按 finish 分支；截断绝不当正常结束，宁可显式标记。</li><li>终止条件随会话状态装配：助手轮用 eos 集合，工具轮用结束标签 stop，来源是模板契约。</li><li>半句话回填是条件前缀 OOD，错误无报错、只有字段知道。</li><li>会话的终止配置是元数据，随会话迁移，换引擎不丢。</li><li>出处：据开放 API 的 finish_reason 约定与 Hugging Face chat template 机制整理；单请求语义见 stop sequences 课。</li></ul>',7))])}const _=r(p,[["render",c]]);export{u as __pageData,_ as default};
